"""Private, hand-authored batch 09m. Not registered or published by this module.

Every tuple below contains independently written prose. The helpers only serialize
and rotate complete label/signal pairs; they do not borrow scenes across slots.
"""
from question_authoring import question as _question, pack as _pack, source as _source

PACKS = []
SOURCES = []


def S(identifier, title, url, kind, supports, limits):
    card = _source(identifier, title, url, kind, supports, limits)
    card['checked_at'] = '2026-10-31'
    SOURCES.append(card)


def Q3(number, scene, sources, v1, alt1, alt2, purpose, boundary=''):
    boundary = boundary or ('只解释题中实际行动的投入重点，不据效率、成功、能力或现实品德判断；'
                            '没有体验时继续换同槽已核实情境，未体验不计分。')
    q = _question(number, scene, v1[0], v1[1], v1[2], purpose, sources,
                  (alt1[0], alt1[1], alt1[2]), boundary)
    third = _question(number, scene, alt2[0], alt2[1], alt2[2], purpose, sources,
                      (alt2[0], alt2[1], alt2[2]), boundary)['variants'][0]
    third['key'] = 'ALT2'
    third['scene'] = scene + '的第二替代情境'
    q['variants'].append(third)
    return q


def P(identifier, title, game_id, scope, routes, notes=()):
    # Each native rule path supplies its own twelve fully written slots.
    p = _pack(identifier, title, [game_id], scope, routes[0][2], notes)
    for slot in p['slots']:
        slot['variants'] = []
    p['modes'] = []
    for mode_id, label, questions in routes:
        assert len(questions) == 12 and [q['number'] for q in questions] == list(range(1, 13))
        initial = {}
        for q, slot in zip(questions, p['slots']):
            for raw in q['variants']:
                v = {k: value for k, value in raw.items() if k != 'key'}
                v['id'] = slot['id'] + '.' + mode_id.upper() + '.' + raw['key']
                v['modes'] = [mode_id]
                slot['variants'].append(v)
                if raw['key'] == 'V1':
                    initial[slot['id']] = v['id']
        p['modes'].append({'id': mode_id, 'label': label, 'initial_variants': initial})
    p['status'] = 'private_authoring_pending_independent_review'
    p['author_review'] = 'author_sources_checked_and_full_copy_self_reviewed'
    PACKS.append(p)
    return p


