P('ase9mv5', 'ARK Survival Evolved：孤岛生存与原生创造', 'steam-346110',
  'PC ASE 本体 The Island；生存共有机制适用单人、PvE或PvP，原生Creative另路；不含ASA改进、DLC、模组、硬核删角或独立SOTF。',
  [('survival', '生存：单人／PvE／PvP共有机制', ASE_SURVIVAL),
   ('creative', '已开启原生 Creative', ASE_CREATIVE)],
  ['服务器互相攻击、掉落和建造权限按实际设置；共有生存题不预设敌方基地可被破坏。',
   'Creative仅指单机或获授权会话的原生状态；不默认另开穿墙、刷物、任意地形拆除或无限设备燃料。',
   '每路12槽×3独立情境；槽1—8当前行动，9—12真实过去；真人合作或交战均有独立单人情境。'])

