   ('你与真人朋友当前没有决斗计划，已一起开了一个城堡工地；有人想出门取料，有人想补房间，双方都有可做内容。你先做什么？',
    '谈好这轮共同目标、谁取什么、谁做哪间房，以及不同人的进度何时接上|先陪熟悉的朋友去他们想玩的地方，想继续一起发生的经历|自己按个人主题实际调整一处城堡入口和空间呈现|先查看当前身体状态、血池与携带补给，再定自己这一轮',
    'q o a survival_status_review'),
