P('enshrouded9mv5', '雾锁王国：1.0本体探索、建造与机关', 'steam-1203620',
  'PC已发1.0本体单人或真人合作共有机制；不同难度的额外饥饿/掉落不作前提。Sparkworks与飞行建造须已解锁，不另假定无限资源Creative模式。',
  [('survival', '本体冒险与建造', ENS_SURVIVAL)],
  ['当前版本以10月15日1.0与21日Hotfix正文核实；未发布路线图或旧Early Access承诺不算现有功能。',
   'Sparkworks是存档内解锁工具；任意社区共享作品的自定义规则不作为必备，机关题只问自己当前确实可改的装置。',
   '种苗、成株种植和水源配方分开，不套其他作品的普遍逐株浇水；NPC工匠提供制作与剧情不算真人。',
   '每槽三项独立情境，含基础出行、制作、火坛内编辑或真实起步回顾。'])

