    '先核对Field Guide里已经出现的一段玩法说明，再继续自己的尝试|先比较当前可选工具、蓝图与升级方案，暂不投入|在制作界面按已有材料确认用料，排好这轮执行制作与整理产物的顺序，再亲自尝试|先核对眼前已有材料与实际存量',
