   ('回想你确实只独自玩过Mission起步采集、制作与第一处箱子的一段经历。哪件已发生的事最接近当时的重点？',
    '我在制作界面按已有材料与配方确认过用料，排清执行制作与整理产物的先后，再亲自照顺序尝试过|我先核对过身体状态、氧气与手头补给|我实际把已得物品在随身与当前箱子之间存取好|我给当时已经放下的临时工地补记了建设过程',
    'crafting_action_sequence survival_status_review item_handling_action construction_process_recording'),
